-- Add columns needed for frontend compatibility
ALTER TABLE products ADD COLUMN IF NOT EXISTS legacy_id integer UNIQUE;
ALTER TABLE products ADD COLUMN IF NOT EXISTS collection TEXT;

-- Enable real-time for products table
ALTER PUBLICATION supabase_realtime ADD TABLE products;

-- Seed all built-in products
ON CONFLICT (legacy_id) DO NOTHING;

-- Update legacy products that already exist (in case seed runs after table has data)
UPDATE products SET
  collection = CASE
    WHEN category = 'Presets' THEN 'presets'
    WHEN category = 'Motion Graphics' THEN 'motion-graphics'
    WHEN category = 'Project Files' THEN 'project-files'
    WHEN category = 'Free Assets' THEN 'free-assets'
    WHEN category = 'Sound Effects' THEN 'sound-effects'
    ELSE 'uncategorized'
  END
WHERE collection IS NULL AND legacy_id IS NOT NULL;
